import csv,numpy as np
from pymatgen.core import Structure
D={x['candidate_id']:x for x in csv.DictReader(open('nlo_pool.csv'))}
sets={
'c024':{'Si':('C',2.2)},'c025':{'Si':('C',2.2)},'c026':{'Si':('C',2.2)},'c027':{'Si':('C',2.2)},'c028':{'Si':('C',2.2)},'c029':{'Si':('C',2.2)},'c037':{'Be':('Se',2.6)},
**{f'c0{i}':{'B':('S',2.1)} for i in range(40,46)},
'c046':{'Zn':('S',2.7)},'c050':{'Zn':('S',2.7),'Ga':('S',2.7)},'c051':{'Zn':('S',2.7),'Ga':('S',2.7)},'c052':{'Zn':('S',2.7),'Ga':('S',2.7)},'c053':{'Ga':('Cl',2.5)},'c057':{'Al':('S',2.6)},'c067':{'Zn':('S',2.7)},'c076':{'Ga':('S',2.7)},'c077':{'Ga':('S',2.7)},'c078':{'Ga':('S',2.7)},'c081':{'Al':('S',2.6),'Zn':('S',2.7)},'c084':{'Sn':('Cl',3.3)},'c085':{'Sn':('Cl',3.3)},'c086':{'Ge':('Cl',2.8)}}
for cid,active in sets.items():
 s=Structure.from_str(D[cid]['poscar'],fmt='poscar'); T=np.zeros((3,3,3)); bonds=0
 for site in s:
  e=str(site.specie)
  if e not in active: continue
  ae,cut=active[e]
  for n in s.get_neighbors(site,cut):
   if str(n.specie)!=ae: continue
   v=n.coords-site.coords; u=v/np.linalg.norm(v); T += np.einsum('i,j,k->ijk',u,u,u); bonds+=1
 mx=np.max(np.abs(T))/s.volume; norm=np.linalg.norm(T)/s.volume
 print(f'{cid} {D[cid]["formula"]:<17} bonds={bonds:2} geom_max={mx:.5f} norm={norm:.5f}')
