import csv
from pymatgen.core import Structure
D={x['candidate_id']:x for x in csv.DictReader(open('nlo_pool.csv'))}
for cid in 'c024 c025 c026 c028 c029'.split():
 s=Structure.from_str(D[cid]['poscar'],fmt='poscar')
 print('\n',cid)
 for el in ['Si','C']:
  print(el,[(round(float(x.frac_coords[0])%1,3),round(float(x.frac_coords[1])%1,3),round(float(x.frac_coords[2])%1,4)) for x in sorted([q for q in s if str(q.specie)==el],key=lambda q:q.frac_coords[2])])
